import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/skills/commands.md","filePath":"modules/skills/commands.md","lastUpdated":0}`),a={name:`modules/skills/commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to “命令与权限”">​</a></h1><p>EmakiSkills 的主命令是 <code>/emakiskills</code>，别名为 <code>/eskills</code>。玩家用它打开技能界面、切换施法模式和升级技能；管理员用它管理等级、清空槽位、检查档案、重新扫描技能来源和重载配置。</p><h2 id="命令注册" tabindex="-1">命令注册 <a class="header-anchor" href="#命令注册" aria-label="Permalink to “命令注册”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>主命令</td><td><code>/emakiskills</code></td></tr><tr><td>别名</td><td><code>/eskills</code></td></tr><tr><td>命令注册权限</td><td><code>emakiskills.use</code></td></tr><tr><td>命令提示</td><td><code>/eskills</code> 或 <code>/eskills help</code></td></tr></tbody></table><p>命令本身以 <code>emakiskills.use</code> 注册：缺少该权限时整条命令（包含 <code>help</code>）无法执行，子命令里的 <code>emakiskills.admin</code> 兜底判断也不会被触发。该权限默认 <code>true</code>，因此实际约束主要来自显式取反权限的情况。</p><h2 id="命令列表" tabindex="-1">命令列表 <a class="header-anchor" href="#命令列表" aria-label="Permalink to “命令列表”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/eskills help</code></td><td>命令注册权限</td><td>输出命令帮助列表。不带参数执行 <code>/eskills</code> 时同样显示。help 分支自身不再额外检查权限。</td></tr><tr><td><code>/eskills gui</code></td><td><code>emakiskills.use</code> 或 <code>emakiskills.admin</code></td><td>打开技能 GUI。控制台等非玩家执行会提示仅限玩家。</td></tr><tr><td><code>/eskills castmode &lt;on|off|toggle&gt;</code></td><td><code>emakiskills.use</code> 或 <code>emakiskills.admin</code></td><td>开启、关闭或切换施法模式。</td></tr><tr><td><code>/eskills upgrade &lt;skill&gt;</code></td><td><code>emakiskills.use</code> 或 <code>emakiskills.admin</code></td><td>尝试升级指定技能，反馈文案来自 <code>upgrade.*</code>。</td></tr><tr><td><code>/eskills level get &lt;player&gt; &lt;skill&gt;</code></td><td><code>emakiskills.admin</code></td><td>查看玩家指定技能等级。</td></tr><tr><td><code>/eskills level set &lt;player&gt; &lt;skill&gt; &lt;value&gt;</code></td><td><code>emakiskills.admin</code></td><td>设置玩家指定技能等级。</td></tr><tr><td><code>/eskills level add &lt;player&gt; &lt;skill&gt; &lt;value&gt;</code></td><td><code>emakiskills.admin</code></td><td>增加玩家指定技能等级。</td></tr><tr><td><code>/eskills clearslot &lt;player&gt; &lt;slot&gt;</code></td><td><code>emakiskills.admin</code></td><td>清空玩家指定技能槽绑定。</td></tr><tr><td><code>/eskills inspect [player]</code></td><td><code>emakiskills.use</code> 或 <code>emakiskills.admin</code></td><td>查看玩家技能档案和已绑定的触发器槽位。</td></tr><tr><td><code>/eskills resync [player]</code></td><td><code>emakiskills.admin</code></td><td>校验并重新同步玩家技能槽绑定。省略玩家时可作用于自己。</td></tr><tr><td><code>/eskills debug [status|on|off|player|module] [...]</code></td><td><code>emakiskills.debug</code> 或 <code>emakiskills.admin</code></td><td>输出或切换调试状态。技能模块为 <code>cast</code>、<code>unlock</code>、<code>upgrade</code>、<code>slot</code>。</td></tr><tr><td><code>/eskills reload</code></td><td><code>emakiskills.reload</code> 或 <code>emakiskills.admin</code></td><td>异步重载技能、资源、GUI、语言和主配置，并输出耗时。</td></tr></tbody></table><p>未识别的子命令会回复 <code>general.unknown_command</code>。<code>level</code>、<code>clearslot</code> 要求参数数量与整数 <code>value</code>/<code>slot</code> 合法，否则回复 <code>general.invalid_args</code>。</p><h3 id="参数补全" tabindex="-1">参数补全 <a class="header-anchor" href="#参数补全" aria-label="Permalink to “参数补全”">​</a></h3><table tabindex="0"><thead><tr><th>位置</th><th>补全内容</th></tr></thead><tbody><tr><td>第 1 参数</td><td>十个子命令字面量。</td></tr><tr><td><code>castmode</code> 第 2 参数</td><td><code>on</code>、<code>off</code>、<code>toggle</code>。</td></tr><tr><td><code>upgrade</code> 第 2 参数</td><td>玩家已解锁、已开启升级且未满级的技能 id；控制台执行时补全全部技能 id。</td></tr><tr><td><code>level</code> 第 2 参数</td><td><code>get</code>、<code>set</code>、<code>add</code>。</td></tr><tr><td><code>clearslot</code> 第 2 参数 / <code>level</code> 第 3 参数</td><td>在线玩家名。</td></tr><tr><td><code>clearslot</code> 第 3 参数</td><td>槽位 <code>0</code>~<code>8</code>。</td></tr><tr><td><code>level</code> 第 4 参数</td><td>全部技能 id。</td></tr><tr><td><code>level set/add</code> 第 5 参数</td><td><code>1</code>、<code>2</code>、<code>5</code>、<code>10</code>。</td></tr></tbody></table><h2 id="权限节点" tabindex="-1">权限节点 <a class="header-anchor" href="#权限节点" aria-label="Permalink to “权限节点”">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>emakiskills.use</code></td><td>true</td><td>允许使用基础技能功能、打开 GUI、切换施法模式与释放技能；同时是命令注册权限。</td></tr><tr><td><code>emakiskills.reload</code></td><td>op</td><td>允许重载配置。</td></tr><tr><td><code>emakiskills.admin</code></td><td>op</td><td>允许管理技能等级、清空槽位、重新同步，并作为基础功能的管理员兜底权限。</td></tr><tr><td><code>emakiskills.debug</code></td><td>op</td><td>允许输出调试信息。</td></tr></tbody></table><h2 id="先用哪个命令" tabindex="-1">先用哪个命令 <a class="header-anchor" href="#先用哪个命令" aria-label="Permalink to “先用哪个命令”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>先执行</th><th>目的</th></tr></thead><tbody><tr><td>玩家要查看或绑定技能</td><td><code>/eskills gui</code></td><td>打开技能界面。</td></tr><tr><td>主动技能无法释放</td><td><code>/eskills inspect [player]</code></td><td>查看玩家档案是否加载，以及已绑定的触发器槽位绑定状态。</td></tr><tr><td>玩家换装备后技能没刷新</td><td><code>/eskills resync &lt;player&gt;</code></td><td>重新扫描技能来源。</td></tr><tr><td>技能等级异常</td><td><code>/eskills level get &lt;player&gt; &lt;skill&gt;</code></td><td>确认玩家档案中的真实等级。</td></tr><tr><td>槽位绑定到已删除技能</td><td><code>/eskills clearslot &lt;player&gt; &lt;slot&gt;</code></td><td>清理指定技能槽。</td></tr><tr><td>改了技能、资源或 GUI</td><td><code>/eskills reload</code></td><td>重载运行配置。</td></tr></tbody></table><h2 id="常见操作" tabindex="-1">常见操作 <a class="header-anchor" href="#常见操作" aria-label="Permalink to “常见操作”">​</a></h2><h3 id="打开技能界面" tabindex="-1">打开技能界面 <a class="header-anchor" href="#打开技能界面" aria-label="Permalink to “打开技能界面”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eskills gui</span></span></code></pre></div><p>技能 GUI 用于查看已解锁技能、技能等级、槽位绑定、升级入口和触发器选择入口。</p><h3 id="切换施法模式" tabindex="-1">切换施法模式 <a class="header-anchor" href="#切换施法模式" aria-label="Permalink to “切换施法模式”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eskills castmode toggle</span></span>
<span class="line"><span>/eskills castmode on</span></span>
<span class="line"><span>/eskills castmode off</span></span></code></pre></div><p>施法模式会影响主动技能触发。默认配置可让玩家通过 F 键进入或退出施法模式；重登后是否恢复由 <code>cast_mode.restore_last_state_on_join</code> 控制。</p><h3 id="管理技能等级" tabindex="-1">管理技能等级 <a class="header-anchor" href="#管理技能等级" aria-label="Permalink to “管理技能等级”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eskills level get Steve fireball</span></span>
<span class="line"><span>/eskills level set Steve fireball 3</span></span>
<span class="line"><span>/eskills level add Steve fireball 1</span></span></code></pre></div><p>等级管理会直接影响技能参数、资源消耗、脚本变量和升级判断。等级会被夹取到 <code>[1, max_level]</code>；未开启升级的技能最大等级为 <code>1</code>。调整后建议使用 <code>inspect</code> 确认玩家档案。</p><h3 id="清空技能槽" tabindex="-1">清空技能槽 <a class="header-anchor" href="#清空技能槽" aria-label="Permalink to “清空技能槽”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eskills clearslot Steve 1</span></span></code></pre></div><p>当玩家槽位绑定到已删除技能、触发器冲突或 GUI 无法正常解绑时，可以使用该命令清理指定槽位。槽位非法时状态服务会拒绝并回复失败。</p><h3 id="重新扫描技能来源" tabindex="-1">重新扫描技能来源 <a class="header-anchor" href="#重新扫描技能来源" aria-label="Permalink to “重新扫描技能来源”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eskills resync Steve</span></span></code></pre></div><p>适用于以下情况：</p><ul><li>玩家更换装备后技能来源未即时刷新。</li><li>EmakiItem 套装或物品效果发生变化。</li><li>外部模块发放或移除了技能来源。</li><li>配置重载后需要刷新在线玩家状态。</li></ul><h3 id="输出调试信息" tabindex="-1">输出调试信息 <a class="header-anchor" href="#输出调试信息" aria-label="Permalink to “输出调试信息”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eskills debug</span></span>
<span class="line"><span>/eskills debug status</span></span>
<span class="line"><span>/eskills debug on</span></span>
<span class="line"><span>/eskills debug off</span></span>
<span class="line"><span>/eskills debug player Steve</span></span>
<span class="line"><span>/eskills debug module cast</span></span></code></pre></div><table tabindex="0"><thead><tr><th>子命令</th><th>说明</th></tr></thead><tbody><tr><td><code>status</code></td><td>输出当前调试状态与正在跟踪的玩家；<code>debug</code> 不带参数时同样输出状态，未识别的子命令也回落到状态输出。</td></tr><tr><td><code>on</code> / <code>off</code></td><td>打开或关闭全部调试输出。</td></tr><tr><td><code>player &lt;玩家&gt;</code></td><td>跟踪指定玩家的调试输出。</td></tr><tr><td><code>module &lt;模块&gt;</code></td><td>切换单个调试模块。技能模块为 <code>cast</code>、<code>unlock</code>、<code>upgrade</code>、<code>slot</code>；共享模块为 <code>action</code>、<code>item_operation</code>、<code>variables</code>、<code>placeholder</code>、<code>gui</code>、<code>chat_input</code>。</td></tr></tbody></table><p>命令帮助里写的是 <code>debug &lt;status|player|module|all&gt; [...]</code>，实际子命令以本节为准。</p><h2 id="排查建议" tabindex="-1">排查建议 <a class="header-anchor" href="#排查建议" aria-label="Permalink to “排查建议”">​</a></h2><ul><li>技能不显示：检查技能定义是否加载、玩家是否拥有技能来源、技能等级是否大于 0。</li><li>技能无法释放：检查施法模式、触发器绑定、冷却、全局延迟、资源消耗和条件。</li><li>被动技能不触发：检查 <code>trigger_type: passive</code>、<code>passive_triggers</code> 和全局被动触发器是否启用。</li><li>GUI 绑定失败：检查触发器是否禁用、是否与已有触发器冲突、槽位编号是否有效。</li><li>MythicMobs 技能无效果：检查 MythicMobs 是否安装、技能 ID 是否正确、脚本模式是否为 <code>mythic</code> 或 <code>hybrid</code>。</li><li>玩家看不到失败原因：文案取自 <code>lang/&lt;language&gt;.yml</code>；确认该语言文件存在对应键，而不是直接修改源码中的 reasonKey。</li></ul>`,37)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};